pub fn resolved_reference_spine_optional(node: Rc<Node>, kind: ResolvedReferenceKind) -> Option<Rc<Node>> {
    match (*crate::v2_std_node::resolved_reference_body_kind(node.clone())).clone() {
    ResolvedReferenceMarking::MarkedReference { kind: found, .. } => if (found.clone() == kind.clone()) {
        node.children.clone().iter().cloned().fold(crate::std_optional::optional_absent(), |acc: Option<_>, edge: Rc<Edge>| crate::std_optional::optional_present(edge.target.clone()))
    } else {
        crate::std_optional::optional_absent()
    },
    ResolvedReferenceMarking::NotMarkedReference => crate::std_optional::optional_absent(),
}
}

