#[derive(Debug, Clone, PartialEq, serde::Serialize)]
pub struct DeclarationDenotation {
    pub declaration: QualifiedName,
    pub type_arguments: Rc<Vec<Rc<Node>>>,
}

pub fn declaration_denotation_is_optional(denotation: Rc<DeclarationDenotation>) -> bool {
    (denotation.declaration.clone() == optional_declaration_identity())
}

pub fn declaration_denotation_of_type(t: Rc<Node>) -> Option<Rc<DeclarationDenotation>> {
    match (*t.kind.clone()).clone() {
    NodeKind::TypeNode { connective: ref __rc_connective, .. } => { match __rc_connective.as_ref() {
    Connective::Instantiation => { let __fm = crate::v2_std_node::positional_child_target_nodes(t.clone()); if __fm.is_empty() { crate::std_optional::optional_absent() } else { let head = (*__fm)[0].clone(); let arguments: Rc<Vec<_>> = Rc::new(__fm.skip(1)); match declaration_reference_path_optional(head.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(path) => crate::std_optional::optional_present(Rc::new(DeclarationDenotation {
    declaration: path.clone(),
    type_arguments: arguments.clone(),
})),
} } },
    _ => match declaration_reference_path_optional(t.clone()) {
    std::option::Option::None => crate::std_optional::optional_absent(),
    Some(path) => crate::std_optional::optional_present(Rc::new(DeclarationDenotation {
    declaration: path.clone(),
    type_arguments: Rc::new(vec![]),
})),
},
} },
    NodeKind::ComputationNode { behavior: _, .. } => crate::std_optional::optional_absent(),
}
}

pub fn parameter_reference_path_optional(node: Rc<Node>) -> Option<QualifiedName> {
    resolved_reference_path_optional(node, ResolvedReferenceKind::ParameterReferenceKind)
}

pub fn resolved_reference_path_optional(node: Rc<Node>, kind: ResolvedReferenceKind) -> Option<QualifiedName> {
    match resolved_reference_spine_optional(node, kind) {
    Some(spine) => if qualified_name_spine_shape_present(spine.clone()) {
        match (*qualified_name_from_node(spine.clone())).clone() {
    Outcome::Accepted { value: qn, .. } => crate::std_optional::optional_present(qn.clone()),
    Outcome::Rejected { diagnostics: _, .. } => crate::std_optional::optional_absent(),
}
    } else {
        crate::std_optional::optional_absent()
    },
    std::option::Option::None => crate::std_optional::optional_absent(),
}
}

pub fn qualified_name_owning_module(roster: Rc<Vec<QualifiedName>>, target: QualifiedName) -> Option<QualifiedName> {
    crate::std_algebra::fold_list(roster, crate::std_optional::optional_absent(), |best, candidate| if crate::std_algebra::is_prefix_of(candidate.clone(), target.clone(), symbol_eq) {
        match best.clone() {
    std::option::Option::None => crate::std_optional::optional_present(candidate.clone()),
    Some(current) => if (crate::std_algebra::length(candidate.clone()) > crate::std_algebra::length(current.clone())) {
            crate::std_optional::optional_present(candidate.clone())
        } else {
            best.clone()
        },
}
    } else {
        best.clone()
    })
}

