pub fn equality_derived_qn_fold_status(a: Rc<QnFoldStatus>, b: Rc<QnFoldStatus>) -> bool {
    match (*a.clone()).clone() {
    QnFoldStatus::QnFoldInit => match (*b.clone()).clone() {
    QnFoldStatus::QnFoldInit => true,
    _ => false,
},
    QnFoldStatus::QnFoldHeadSeen { sym: eqa_sym, .. } => match (*b.clone()).clone() {
    QnFoldStatus::QnFoldHeadSeen { sym: eqb_sym, .. } => (eqa_sym.clone() == eqb_sym.clone()),
    _ => false,
},
    QnFoldStatus::QnFoldTailSeen { tail: eqa_tail, .. } => match (*b.clone()).clone() {
    QnFoldStatus::QnFoldTailSeen { tail: eqb_tail, .. } => (eqa_tail.clone() == eqb_tail.clone()),
    _ => false,
},
    QnFoldStatus::QnFoldDone { qn: eqa_qn, .. } => match (*b.clone()).clone() {
    QnFoldStatus::QnFoldDone { qn: eqb_qn, .. } => (eqa_qn.clone() == eqb_qn.clone()),
    _ => false,
},
    QnFoldStatus::QnFoldError { diag: eqa_diag, .. } => match (*b.clone()).clone() {
    QnFoldStatus::QnFoldError { diag: eqb_diag, .. } => crate::v2_std_diagnostic::equality_derived_diagnostic(eqa_diag.clone(), eqb_diag.clone()),
    _ => false,
},
}
}

pub fn equality_derived_declaration_denotation(a: Rc<DeclarationDenotation>, b: Rc<DeclarationDenotation>) -> bool {
    ((a.declaration.clone() == b.declaration.clone()) && crate::std_algebra::zip_eq(a.type_arguments.clone(), b.type_arguments.clone(), |eqp0, eqq0| crate::v2_std_node::node_equal_ignoring_provenance(eqp0.clone(), eqq0.clone())))
}

